"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["3569"],{2622(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>r,contentTitle:()=>l,toc:()=>d,assets:()=>c});var o=JSON.parse('{"id":"m26-cicd-automation/lesson","title":"Lesson: Source Control and CI/CD Automation","description":"Every module in this course that talks to GitHub so far reads one thing at a time: a repository\'s","source":"@site/docs/m26-cicd-automation/lesson.md","sourceDirName":"m26-cicd-automation","slug":"/m26-cicd-automation/lesson","permalink":"/307-aipython-site/docs/m26-cicd-automation/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: Source Control and CI/CD Automation"},"sidebar":"courseSidebar","previous":{"title":"Deep Dive (Part 2)","permalink":"/307-aipython-site/docs/m25-safe-cloud-remediation/deep-dive"},"next":{"title":"Lab: Source Control and CI/CD Automation","permalink":"/307-aipython-site/docs/m26-cicd-automation/lab"}}'),a=n(4848),s=n(8453),i=n(7684);let r={sidebar_position:1,title:"Lesson: Source Control and CI/CD Automation"},l="Source Control and CI/CD Automation",c={},d=[{value:"1. The loan officer, not the loan applicant",id:"1-the-loan-officer-not-the-loan-applicant",level:2},{value:"2. Reading CI/CD state, not reimplementing it",id:"2-reading-cicd-state-not-reimplementing-it",level:2},{value:"3. Six sources, one report",id:"3-six-sources-one-report",level:2},{value:"4. Fetching evidence and judging it are two different jobs",id:"4-fetching-evidence-and-judging-it-are-two-different-jobs",level:2},{value:"5. A source you cannot reach is not a source that passed",id:"5-a-source-you-cannot-reach-is-not-a-source-that-passed",level:2},{value:"Common pitfalls",id:"common-pitfalls",level:2}];function h(e){let t={admonition:"admonition",code:"code",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(i.A,{src:"decks/m26-concepts.html",title:"M26 \u2014 Source Control and CI/CD Automation"}),"\n",(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"source-control-and-cicd-automation",children:"Source Control and CI/CD Automation"})}),"\n",(0,a.jsx)(t.p,{children:"Every module in this course that talks to GitHub so far reads one thing at a time: a repository's\nsummary in Module 9, a list of workflow runs also in Module 9. A real release decision needs more\nthan one answer. Before a team ships a service, someone asks a few questions. Is the pull request\nactually approved and merged? Did the last CI run pass? Did every required check finish, and did\nthey all pass? Does a build artifact actually exist? Does the deployment record point at the right\ncontainer image? This module builds a tool that answers all of this in one report, read straight\nfrom GitHub's own records. It never guesses, and it never does any of that work itself."}),"\n",(0,a.jsx)(t.admonition,{title:"Why this matters at work",type:"info",children:(0,a.jsx)(t.p,{children:"A release usually fails not because one thing broke, but because one thing was never checked. A\npull request merges clean, CI is green, but nobody notices that the build artifact from that run has\nexpired before anyone tries to deploy it. Or the deployment record still points at last week's image\ntag. A person checking five different browser tabs, under time pressure, before a release, will miss\none of them sooner or later. A tool that pulls the same five signals every single time, and says\nplainly when it could not check one of them, does not get tired and does not skip a tab."})}),"\n",(0,a.jsx)(t.h2,{id:"1-the-loan-officer-not-the-loan-applicant",children:"1. The loan officer, not the loan applicant"}),"\n",(0,a.jsx)(t.p,{children:'Imagine you are a loan officer at a bank, deciding whether to approve a loan. You do not trust one\nsignal. You check the applicant\'s credit score, you verify their income with payslips, and you\nconfirm the value of whatever collateral they offer \u2014 three separate checks, each from a different\nsource. A high credit score alone does not get the loan approved if income cannot be verified. And\nif the income-verification service is down for the day, you do not approve the loan anyway assuming\nit will probably be fine. You mark the application "on hold, income unverified" and wait. Approving\non a guess is worse than a delay.'}),"\n",(0,a.jsx)(t.p,{children:"That is exactly the job this module's tool does for a software release. It checks the pull request's\nstatus, the CI run's result, individual check runs, whether a build artifact exists, and the\ndeployment record's image reference \u2014 five separate signals, each read from GitHub's own records. It\nnever approves anything itself. It reports what it found, plainly, including the times it could not\ncheck something at all. The team \u2014 a release engineer, a deploy pipeline, an on-call engineer \u2014\ndecides what to do with that report. This is the same read-only discipline Module 19's\nservice-readiness report and Module 24's cloud audit already used: gather evidence from several real\nsources, and never let the tool that gathers evidence also decide to act."}),"\n",(0,a.jsx)(t.h2,{id:"2-reading-cicd-state-not-reimplementing-it",children:"2. Reading CI/CD state, not reimplementing it"}),"\n",(0,a.jsx)(t.p,{children:"You could technically write Python that re-runs a test suite, or re-checks a merge conflict by\nreading Git internals directly. This module's tool does none of that. Every piece of evidence it\nuses is something GitHub's own systems already worked out and already published through its API \u2014\nthe same API a pull request page, a check-run badge, or an Actions tab in your browser reads from.\nThe tool's whole job is to read that published state and combine it. It never recalculates it."}),"\n",(0,a.jsxs)(t.p,{children:["That boundary matters for a reason beyond neatness. GitHub's CI system, its branch-protection rules,\nand its merge-readiness logic can change \u2014 a new required check gets added, a branch-protection rule\ngets stricter \u2014 without this project's code ever needing to change to match. A tool that\nreimplemented \"is this PR mergeable\" in its own Python would drift out of sync with GitHub's real\nrules the first time someone added a new required review. Instead, this tool reads GitHub's own\n",(0,a.jsx)(t.code,{children:"mergeable_state"})," field, which is what that value is called on the pull request itself \u2014 GitHub sets\nit to ",(0,a.jsx)(t.code,{children:'"clean"'}),", ",(0,a.jsx)(t.code,{children:'"blocked"'}),", ",(0,a.jsx)(t.code,{children:'"dirty"'}),", or a few other values, and computes it fresh every time. So\nthis tool is always exactly as current as GitHub's own answer."]}),"\n",(0,a.jsx)(t.h2,{id:"3-six-sources-one-report",children:"3. Six sources, one report"}),"\n",(0,a.jsx)(t.mermaid,{value:'flowchart LR\n    PR["Pull request\\n(merged? approved? blocked?)"] --\x3e AG\n    CI["Latest workflow run\\n(succeeded? failed? running?)"] --\x3e AG\n    CH["Check runs\\n(pass / fail / pending)"] --\x3e AG\n    AR["Build artifact\\n(present? expired?)"] --\x3e AG\n    RL["Latest release\\n(informational only)"] --\x3e AG\n    DP["Deployment record\\n(image tag / digest)"] --\x3e AG\n    AG["evaluate_release_readiness()\\npure, no network calls"] --\x3e RPT["ReleaseReadinessReport\\nverdict: ready / not_ready"]'}),"\n",(0,a.jsxs)(t.p,{children:["Five of these six sources gate the verdict: the pull request, CI, check runs, the build artifact,\nand the deployment record. If any one of them comes back ",(0,a.jsx)(t.code,{children:"FAIL"}),", the whole report is ",(0,a.jsx)(t.code,{children:"not_ready"}),' \u2014\nthe same "one bad signal blocks approval" rule you followed as the loan officer above. The sixth\nsource, the latest release, is informational only. Knowing the last shipped version is useful\ncontext for a release engineer reading the report. But "no release has ever been published yet" is\nnot itself a reason to block the very first one, so it never gates the verdict.']}),"\n",(0,a.jsx)(t.h2,{id:"4-fetching-evidence-and-judging-it-are-two-different-jobs",children:"4. Fetching evidence and judging it are two different jobs"}),"\n",(0,a.jsx)(t.p,{children:'Just like Module 24\'s cloud audit, this module keeps two kinds of code strictly apart. Six small\nfunctions, one per source, talk to GitHub. Each one calls exactly one endpoint, catches every way\nthat call can fail, and hands back the plain facts it found: a pull request\'s merge state, a\nworkflow run\'s conclusion, a list of check names that failed. None of these functions decides\nanything. They never contain the words "ready," "PASS," or "FAIL" anywhere in their code. They only\nreport what GitHub said.'}),"\n",(0,a.jsxs)(t.p,{children:["A separate function, ",(0,a.jsx)(t.code,{children:"evaluate_release_readiness()"}),", does the judging. It takes the six\nalready-gathered facts and turns them into a verdict. It never opens a network connection, never\nimports the HTTP library this project uses, and never calls any of the six fetching functions\nitself. That separation is not just a style choice. It means the judgment logic can be tested\ncompletely on its own, by handing it facts you typed by hand, with no live GitHub call, no mocked\nserver, nothing running at all. The Deep Dive proves this separation mechanically, the same way\nModule 24's did."]}),"\n",(0,a.jsx)(t.h2,{id:"5-a-source-you-cannot-reach-is-not-a-source-that-passed",children:"5. A source you cannot reach is not a source that passed"}),"\n",(0,a.jsxs)(t.p,{children:["You, the loan officer with no way to verify income, do not approve the loan. This module's tool\nfollows the same rule for every one of its five gating sources. If a GitHub call times out, gets\nrate-limited, or fails for any other reason, that source's evidence comes back marked \"could not\nfetch this.\" It is never silently treated as if it had passed. A report with even one unreachable\ngating source never says ",(0,a.jsx)(t.code,{children:"ready"}),". This is the same honest-unknown discipline Module 19's\nservice-readiness report already used for the cloud and Kubernetes sections it had no adapter for\nyet, applied here to a source that usually answers, but happened not to this one time."]}),"\n",(0,a.jsxs)(t.p,{children:['Getting this wrong is an easy trap. A first attempt at a tool like this often treats "I could not\ncheck the artifact" as the same thing as "the artifact check passed," because the code path that\nhandles a network error just does nothing, and the verdict logic only ever looks for an explicit\n',(0,a.jsx)(t.code,{children:"FAIL"}),". That silence is the bug. This module's report lists exactly which sources it could not reach\n(",(0,a.jsx)(t.code,{children:"sources_failed"}),"), so a reader never has to guess whether a section was actually checked."]}),"\n",(0,a.jsx)(t.h2,{id:"common-pitfalls",children:"Common pitfalls"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Treating a fetch failure as an automatic pass."}),' If a check-runs call times out, the correct\nreport says "unknown, could not verify" \u2014 never a silent ',(0,a.jsx)(t.code,{children:"PASS"})," that lets a release through on\nevidence that was never actually collected."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Mixing judgment into a fetch function."}),' The moment a function that calls GitHub also decides\n"this means the release is ready," the fetch/aggregate split breaks, and the judgment logic can no\nlonger be tested without a live network call.']}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Assuming CI success alone proves a release is ready."})," A green workflow run says nothing about\nwhether the build artifact from that run still exists, or whether the deployment record actually\npoints at the image that run produced. Check all five gating sources, not just one."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Hardcoding a GitHub token in code."})," This project reads ",(0,a.jsx)(t.code,{children:"GITHUB_TOKEN"})," from the environment the\nsame way Module 9's ",(0,a.jsx)(t.code,{children:"repo-info"})," and ",(0,a.jsx)(t.code,{children:"workflow-runs"})," commands already do \u2014 a token never appears as\na literal string anywhere in this module's source."]}),"\n"]})]})}function u(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(h,{...e})}):h(e)}},7684(e,t,n){n.d(t,{A:()=>s});var o=n(4848);n(6540);var a=n(6497);function s({src:e,title:t="Slides"}){let n=(0,a.Ay)(e);return(0,o.jsxs)("div",{className:"deck_nWXz",children:[(0,o.jsxs)("div",{className:"bar_dOoE",children:[(0,o.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",t]}),(0,o.jsx)("a",{className:"full_PrDQ",href:n,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,o.jsx)("div",{className:"frame_M4DO",children:(0,o.jsx)("iframe",{src:n,title:t,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,t,n){n.d(t,{R:()=>i,x:()=>r});var o=n(6540);let a={},s=o.createContext(a);function i(e){let t=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),o.createElement(s.Provider,{value:t},e.children)}}}]);